head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > P > useNull]<br/>setCellData() 또는 setRow 계열의 메소드로 Column 값 변경 시 null 값을 허용할지 설정합니다.",
    "validation" : [
        // https://inswave01.atlassian.net/browse/WAEA-615
        "useNull=true 일때 setColumnFilter() 메소드, getMatched 계열 메소드, getUnMatched 계열 메소드에서 null 을 처리할 수 있습니다.",
        "useNull=true 일때 정렬이 적용될때는 null 과 ''(Empty String)이 동일하게 처리됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // 조건 설정       
    let properties = {
        useNull: true,        
    };    

    let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // // target 생성
    // $c.gcm.createBasicDataList(cList)
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strGridView = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:dataList ' + strNameSpace + ' ' + cList + ' id="target1" baseNode="list" repeatNode="map">';        
    strTarget += '<w2:columnInfo>';
    strTarget += '<w2:column id="col1" name="name1" dataType="text"></w2:column>';        
    strTarget += '</w2:columnInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<w2:row>';
    strTarget += '<col1><![CDATA[1]]></col1>';    
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<col1><![CDATA[2]]></col1>';    
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<col1><![CDATA[3]]></col1>';    
    strTarget += '</w2:row>';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataList>';    

    $p.data.create(strTarget);

    // gridView 생성   
    // $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');
    strGridView += '<w2:gridView ' + strNameSpace + ' dataList="data:target1" rowStatusVisible="true" checkAllType="false" id="" style="width:500px;height:300px;">';
    strGridView += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strGridView += '<w2:header style="" id="header1">';
    strGridView += '<w2:row style="" id="row1">';
    strGridView += '<w2:column width="70" style="" inputType="text" id="col1" value="name1"></w2:column>';    
    strGridView += '</w2:row>';
    strGridView += '</w2:header>';
    strGridView += '<w2:gBody style="" id="gBody1">';
    strGridView += '<w2:row style="" id="row2">';
    strGridView += '<w2:column width="70" style="" inputType="text" id="col1" value=""></w2:column>';    
    strGridView += '</w2:row>';
    strGridView += '</w2:gBody>';
    strGridView += '</w2:gridView>';    

    scwin["gridView1"] = await $p.dynamicCreate(
        "gridView1",
        "gridView",
        strGridView,
        grp_comp
    );

    scwin.btn_setCellData_onclick();
}



scwin.btn_getAllJSON_onclick = function (e) {
    let rtn = target1.getAllJSON();
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);
};



scwin.btn_setCellData_onclick = function (e) {
	target1.setCellData(0, "col1", "");
    target1.setCellData(1, "col1", null);
    target1.setCellData(2, "col1");

    scwin.btn_getAllJSON_onclick();
};



scwin.btn_setColumnFilter_onclick = function (e) {
	target1.setColumnFilter({type:'row', colIndex:'col1', key:null, condition:'and'});  
};



scwin.btn_getMatchedJSON_onclick = function (e) {
    let rtn = target1.getMatchedJSON("col1", null);    
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);    
};



scwin.btn_getUnmatchedJSON_onclick = function (e) {
    let rtn = target1.getUnmatchedJSON("col1", null);    
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);    
};



scwin.btn_sort_onclick = function (e) {
	target1.sort("col1", 1);

    scwin.btn_getAllJSON_onclick();
};
